fn all_odd_at_odd_positions(arr: &Vec<usize>) -> bool {
    for (index, &value) in arr.iter().enumerate() {
        if index % 2 == 0 && value % 2 != 0 {
            return false; // Even index but odd value
        }
        if index % 2 == 1 && value % 2 != 1 {
            return false; // Odd index but even value
        }
    }
    true // All checks passed
}

fn is_odd_at_odd_index(arr: &Vec<usize>) -> bool {
    for (index, &value) in arr.iter().enumerate() {
        if index % 2 == 1 && value % 2 == 0 {
            return false; // Odd index but even value
        }
    }
    true // All checks passed
}

